import { z } from "zod";

const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

const isHttpUrl = (value: string) => {
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
};

export const propertiesSchema = z.object({
  property_name: z.string().min(1, "validation.required"),
  property_name_en: z.string().optional(),
  property_type_id: z.string().min(1, "validation.required"),
  property_subtype_id: z.string().min(1, "validation.required"),
  project_id: z.string().min(1, "validation.required"),
  size: z.number({ message: "validation.required" })
    .refine((val) => !isNaN(val), { message: "validation.required" })
    .refine((val) => val > 0, { message: "validation.greater_than_zero" }),
  price: z.number({ message: "validation.required" })
    .refine((val) => !isNaN(val), { message: "validation.required" })
    .refine((val) => val >= 0, { message: "validation.positive_number" }),
  status: z.string().min(1, "validation.required"),
  availability_status: z.string().min(1, "validation.required"),
  construction_status: z.string().min(1, "validation.required"),
  finishing_status: z.string().min(1, "validation.required"),

  property_no: z.string().optional(),
  building_name: z.string().optional(),
  plot_size: z.number()
    .refine((val) => isNaN(val) || val >= 0, { message: "validation.positive_number" })
    .optional(),
  bua_size: z.number()
    .refine((val) => isNaN(val) || val >= 0, { message: "validation.positive_number" })
    .optional(),
  bedrooms: z.number()
    .refine((val) => isNaN(val) || (Number.isInteger(val) && val >= 0), {
      message: "validation.positive_integer",
    })
    .optional(),
  bathrooms: z.number()
    .refine((val) => isNaN(val) || (Number.isInteger(val) && val >= 0), {
      message: "validation.positive_integer",
    })
    .optional(),
  parking_spaces: z.number()
    .refine((val) => isNaN(val) || (Number.isInteger(val) && val >= 0), {
      message: "validation.positive_integer",
    })
    .optional(),
  ownership_type: z.string().optional(),
  maid_room: z.boolean().optional(),
  furnish_status: z.string().optional(),
  description: z.string().optional(),
  reference_listed: z.string().optional(),
  broker_license: z.string().optional(),
  agent_license: z.string().optional(),
  zone_name: z.string().optional(),
  city_name: z.string().optional(),
  area_name: z.string().optional(),
  landmark: z.string().optional(),
  maps_url: z.string()
    .refine((val) => !val.trim() || isHttpUrl(val.trim()), { message: "validation.url_invalid" })
    .optional(),
  latitude: z.number()
    .refine((val) => isNaN(val) || (val >= -90 && val <= 90), { message: "validation.latitude_range" })
    .optional(),
  longitude: z.number()
    .refine((val) => isNaN(val) || (val >= -180 && val <= 180), { message: "validation.longitude_range" })
    .optional(),
  dld_permit_number: z.string().optional(),
  dld_barcode: z.string().optional(),
  currency: z.string().optional(),
  price_per_m2: z.number()
    .refine((val) => isNaN(val) || val >= 0, { message: "validation.positive_number" })
    .optional(),
  price_description: z.string().optional(),
  floor: z.string().optional(),
  view: z.string().optional(),
  slug: z.string()
    .refine((val) => !val || SLUG_PATTERN.test(val), { message: "validation.slug_invalid" })
    .optional(),
  meta_title: z.string().optional(),
  meta_description: z.string().optional(),
  payment_plans: z.any().optional(),
});

export type PropertiesInput = z.infer<typeof propertiesSchema>;

export type PropertiesUpdateInput = Partial<PropertiesInput>;
